import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] values = scanner.nextLine().split(" ");
        int[] nums = Arrays.stream(values).mapToInt(Integer::parseInt).toArray();
        int a = Math.min(nums[0], nums[1]);
        int b = Math.max(nums[0], nums[1]);
        int product = a * b;

        Map<Integer, Integer> correctionMapA = new HashMap<>();
        correctionMapA.put(1, Math.min(b % 6, 6 - b % 6));

        Map<Integer, Integer> correctionMapB = new HashMap<>();
        correctionMapB.put(2, 4);
        correctionMapB.put(3, 2);
        correctionMapB.put(7, 2);

        int correction;
        if (correctionMapA.containsKey(a)) {
            correction = correctionMapA.get(a);
        } else {
            int correctionB = correctionMapB.getOrDefault(b, 0);
            correction = (a & 1) * (b & 1) * correctionB;
        }

        System.out.println(product - correction);
        scanner.close();
    }
}
